<template>
  <aside class="studio-sidebar workspace-sidebar" :style="{width:width+'px'}" @dragover.prevent @drop.prevent="drop($event,null)">
    <header class="workspace-header"><button class="workspace-brand workspace-menu-trigger" aria-label="工作区菜单：新建分组、导入、排序" title="工作区菜单 · 新建分组、导入、排序" @click.stop="openMenu('workspace','',$event)"><strong>FlyMind</strong><Icon name="chevron" :size="11"/></button><button class="studio-icon" aria-label="搜索图形" title="搜索（Ctrl+K）" @click="showSearch"><Icon name="search" :size="16"/></button><button class="studio-icon" aria-label="新建图形" title="新建图形" :disabled="props.readOnly" @click="emit('new',currentGroup)"><Icon name="plus" :size="18"/></button></header>
    <slot name="workspace"/>
    <div v-if="searchOpen" class="workspace-search"><Icon name="search" :size="14"/><input ref="searchField" v-model="search" placeholder="搜索图形" aria-label="搜索图形"/><button class="studio-icon" aria-label="关闭搜索" @click="closeSearch"><Icon name="close" :size="13"/></button></div>
    <div v-if="props.showGroupCreation&&!props.readOnly" class="workspace-section-heading"><span>图形</span><button ref="newGroupTrigger" class="studio-icon" :aria-label="newGroup?'收起新建分组':'新建分组'" :title="newGroup?'取消新建分组':'新建分组'" :disabled="!studio.shared||!!studio.pending" @click="newGroup?cancelNewGroup():beginGroup()"><Icon :name="newGroup?'close':'folder-plus'" :size="16"/></button></div>
    <div class="workspace-tree" :class="{dragging}" role="tree" aria-label="图形工作区">
      <form v-if="newGroup" ref="groupForm" class="workspace-inline" @submit.prevent="createGroup" @keydown.esc.prevent.stop="cancelNewGroup()"><Icon name="folder" :size="16"/><input ref="groupField" v-model="groupName" aria-label="新分组名称" placeholder="分组名称" maxlength="80"/><button type="submit" class="studio-icon" aria-label="保存分组" :disabled="!groupName.trim()||!!studio.pending"><Icon name="check" :size="15"/></button><button type="button" class="studio-icon" aria-label="取消新建分组" title="取消（Esc）" :disabled="!!studio.pending" @click="cancelNewGroup()"><Icon name="close" :size="15"/></button></form>
      <template v-if="!query">
        <section v-for="g in studio.workspaceGroups" :key="g.id" class="workspace-group" :data-workspace-group="g.id">
          <div class="workspace-folder" :class="{drop:dropGroup===g.id}" @dragover.prevent.stop="dropGroup=g.id" @dragleave="dropGroup=''" @drop.prevent.stop="drop($event,g.id)" @contextmenu.prevent="openMenu('group',g.id,$event)">
            <input v-if="renaming?.type==='group'&&renaming.id===g.id" v-model="renaming.name" class="workspace-rename" aria-label="修改分组名称" maxlength="80" @blur="finishRename" @keydown.enter="finishRename" @keydown.esc="renaming=null"/>
            <button v-else class="workspace-folder-open" :aria-expanded="expanded.includes(g.id)" @click="toggleGroup(g.id)"><Icon name="chevron" :size="11" :class="{collapsed:!expanded.includes(g.id)}"/><Icon name="folder" :size="16"/><span>{{g.name}}</span></button>
            <button class="workspace-row-menu workspace-menu-trigger" :aria-label="`分组操作 ${g.name}`" @click.stop="openMenu('group',g.id,$event)"><Icon name="more" :size="16"/></button>
          </div>
          <div v-if="expanded.includes(g.id)" class="workspace-group-files" role="group" :aria-label="g.name+'中的图形'" @dragover.prevent.stop="dropGroup=g.id" @drop.prevent.stop="drop($event,g.id)">
            <WorkspaceFileRow v-for="d in groupFiles(g.id)" :key="d.id" v-bind="fileProps(d)" v-on="fileEvents"/>
            <button v-if="!showAll.includes(g.id)&&allGroupFiles(g.id).length>5" class="workspace-show-more" @click="showAll.push(g.id)">展开其余 {{allGroupFiles(g.id).length-5}} 项</button>
          </div>
        </section>
        <div class="workspace-root-files" :class="{drop:dropGroup==='root',separated:studio.workspaceGroups.length}" role="group" aria-label="未分组图形" @dragover.prevent.stop="dropGroup='root'" @dragleave="dropGroup=''" @drop.prevent.stop="drop($event,null)"><WorkspaceFileRow v-for="d in rootFiles" :key="d.id" v-bind="fileProps(d)" v-on="fileEvents"/><span v-if="dragging" class="workspace-drop-hint">移出分组</span></div>
      </template>
      <template v-else><WorkspaceFileRow v-for="d in searchResults" :key="d.id" v-bind="fileProps(d)" v-on="fileEvents"/><p v-if="!searchResults.length" class="workspace-empty">没有找到图形</p></template>
    </div>
    <footer class="workspace-footer"><button @click="trashOpen=true"><Icon name="trash" :size="15"/>回收站</button><button v-if="studio.recoveries.length" @click="emit('recoveries')"><Icon name="restore" :size="15"/>待恢复内容</button></footer>
    <slot name="sidebar-footer"/>
    <div class="workspace-resizer" aria-label="调整侧栏宽度" @pointerdown="resizeSidebar"/>
    <div v-if="menu" class="workspace-popup" role="menu" :style="{left:menu.x+'px',top:menu.y+'px'}">
      <template v-if="menu.type==='workspace'"><button :disabled="props.readOnly||!studio.shared" @click="beginGroup"><Icon name="folder" :size="15"/>新建文件夹分组</button><button :disabled="props.readOnly" @click="emit('import',currentGroup);menu=null"><Icon name="import" :size="15"/>导入图形</button><hr/><button role="menuitemradio" :aria-checked="sortBy==='updated'" @click="sort('updated')">按修改时间<Icon v-if="sortBy==='updated'" name="check" :size="14"/></button><button role="menuitemradio" :aria-checked="sortBy==='created'" @click="sort('created')">按创建时间<Icon v-if="sortBy==='created'" name="check" :size="14"/></button><hr/><button v-if="props.backupEnabled" :disabled="!studio.shared" @click="emit('backup');menu=null"><Icon name="export" :size="15"/>备份工作区</button><button v-if="props.adapter" @click="emit('activity');menu=null">操作记录</button><button @click="emit('help');menu=null"><Icon name="code" :size="15"/>AI 绘图说明</button></template>
      <template v-else-if="menu.type==='file'&&menuFile"><button v-if="props.adapter" @click="emit('activity',menuFile.id);menu=null">操作记录</button><button @click="rename('file',menuFile.id,menuFile.title)"><Icon name="edit" :size="15"/>重命名</button><button @click="duplicateFile(menuFile.id)"><Icon name="copy" :size="15"/>创建副本</button><label>移至分组<select aria-label="移动图形到分组" :value="studio.assignments[menuFile.id]||''" @change="move(menuFile.id,($event.target as HTMLSelectElement).value||null)"><option value="">未分组</option><option v-for="g in studio.workspaceGroups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><hr/><button class="danger" @click="remove(menuFile.id)"><Icon name="trash" :size="15"/>移入回收站</button></template>
      <template v-else-if="menuGroup"><button @click="emit('new',menuGroup.id);menu=null"><Icon name="plus" :size="15"/>新建图形</button><button @click="emit('import',menuGroup.id);menu=null"><Icon name="import" :size="15"/>导入图形</button><button @click="rename('group',menuGroup.id,menuGroup.name)"><Icon name="edit" :size="15"/>重命名</button><button class="danger" @click="deleteGroup(menuGroup.id)"><Icon name="trash" :size="15"/>删除分组</button></template>
    </div>
  </aside>
  <div v-if="trashOpen" class="studio-overlay" @click.self="trashOpen=false"><section class="studio-dialog workspace-trash-dialog" role="dialog" aria-modal="true" aria-label="回收站"><header class="studio-dialog-heading"><h2>回收站</h2><button class="studio-icon" aria-label="关闭回收站" @click="trashOpen=false"><Icon name="close"/></button></header><input v-model="trashSearch" class="studio-search" aria-label="搜索回收站" placeholder="搜索已删除图形"/><div class="workspace-trash-list"><div v-for="item in deletedFiles" :key="item.id" class="workspace-trash-row"><Icon :name="item.kind||'code'" :size="19"/><div><strong>{{item.title}}</strong><small>删除于 {{date(item.deletedAt)}}</small></div><button class="studio-secondary" :aria-label="`恢复 ${item.title}`" :disabled="props.readOnly||!!studio.pending" @click="studio.restoreDeleted(item)">恢复</button><button class="studio-icon danger" :aria-label="`永久删除 ${item.title}`" :disabled="!!studio.pending" @click="purge(item)"><Icon name="trash" :size="16"/></button></div><p v-if="!deletedFiles.length" class="workspace-empty">{{trashSearch?'没有匹配的图形':'回收站为空'}}</p></div><p v-if="studio.storageError" class="studio-data-error" role="alert">{{studio.storageError}}</p></section></div>
</template>
<script setup lang="ts">
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue'
import {useStudio} from '../state/studio'
import {byCreationNewest,byModifiedNewest} from '../core/metadata'
import type {DiagramDocument} from '../core/model'
import type {SidebarAdapter,SidebarFile} from '../services/sidebar-adapter'
import type {TrashItem} from '../services/workspace-types'
import WorkspaceFileRow from './WorkspaceFileRow.vue'
import Icon from './Icon.vue'
const props=withDefaults(defineProps<{adapter?:SidebarAdapter;backupEnabled?:boolean;showGroupCreation?:boolean;readOnly?:boolean}>(),{backupEnabled:true,showGroupCreation:false})
const studio=(props.adapter??useStudio()) as unknown as SidebarAdapter,emit=defineEmits<{(e:'new',group:string|null):void;(e:'import',group?:string|null):void;(e:'file-drop',event:DragEvent,group:string|null):void;(e:'activity',id?:string):void;(e:'backup'):void;(e:'help'):void;(e:'recoveries'):void}>()
function storedGroups(){try{const value=JSON.parse(localStorage.getItem('flymind-expanded-groups')||'[]');return Array.isArray(value)?value.filter(v=>typeof v==='string'):[]}catch{return []}}
const expanded=ref<string[]>(storedGroups()),showAll=ref<string[]>([]),currentGroup=ref<string|null>(null),searchOpen=ref(false),search=ref(''),query=computed(()=>search.value.trim().toLowerCase())
const newGroup=ref(false),groupName=ref(''),dropGroup=ref(''),dragging=ref(false),trashOpen=ref(false),trashSearch=ref(''),searchField=ref<HTMLInputElement>(),groupField=ref<HTMLInputElement>()
const groupForm=ref<HTMLFormElement>(),newGroupTrigger=ref<HTMLButtonElement>()
const width=ref(Math.max(240,Math.min(420,Number(localStorage.getItem('flymind-sidebar-width'))||276))),sortBy=ref(localStorage.getItem('flymind-list-sort')==='created'?'created':'updated')
const menu=ref<{type:'file'|'group'|'workspace';id:string;x:number;y:number}|null>(null),renaming=ref<{type:'file'|'group';id:string;name:string}|null>(null)
const sorted=computed(()=>[...studio.documents].sort(sortBy.value==='created'?byCreationNewest:byModifiedNewest)),rootFiles=computed(()=>sorted.value.filter(d=>!studio.assignments[d.id])),searchResults=computed(()=>sorted.value.filter(d=>d.title.toLowerCase().includes(query.value)))
const menuFile=computed(()=>studio.documents.find(d=>d.id===menu.value?.id)),menuGroup=computed(()=>studio.workspaceGroups.find(g=>g.id===menu.value?.id)),deletedFiles=computed(()=>studio.trash.filter(d=>d.title.toLowerCase().includes(trashSearch.value.toLowerCase())))
watch(expanded,v=>localStorage.setItem('flymind-expanded-groups',JSON.stringify(v)),{deep:true})
watch(()=>[studio.activeId,studio.assignments[studio.activeId]] as const,([active,group])=>{currentGroup.value=group||null;if(group){if(!expanded.value.includes(group))expanded.value.push(group);if(allGroupFiles(group).findIndex(d=>d.id===active)>=5&&!showAll.value.includes(group))showAll.value.push(group)}},{immediate:true})
watch(()=>studio.workspaceGroups,groups=>{if(currentGroup.value&&!groups.some(g=>g.id===currentGroup.value))currentGroup.value=null})
function allGroupFiles(id:string){return sorted.value.filter(d=>studio.assignments[d.id]===id)}
function groupFiles(id:string){const files=allGroupFiles(id);return showAll.value.includes(id)?files:files.slice(0,5)}
function fileProps(d:SidebarFile){return {document:d,active:d.id===studio.activeId,renameValue:renaming.value?.type==='file'&&renaming.value.id===d.id?renaming.value.name:undefined,groupName:studio.workspaceGroups.find(g=>g.id===studio.assignments[d.id])?.name}}
const fileEvents={open:(id:string)=>{currentGroup.value=studio.assignments[id]||null;studio.open(id)},rename:(id:string,title:string)=>rename('file',id,title),menu:(id:string,e:MouseEvent)=>openMenu('file',id,e),updateRename:(value:string)=>{if(renaming.value)renaming.value.name=value},finishRename:()=>finishRename(),cancelRename:()=>{renaming.value=null},dragStart:()=>{dragging.value=true},dragEnd:()=>{dragging.value=false;dropGroup.value=''}}
function date(time?:number){return time?new Date(time).toLocaleString('zh-CN',{hour12:false}):'—'}
function toggleGroup(id:string){currentGroup.value=id;expanded.value=expanded.value.includes(id)?expanded.value.filter(g=>g!==id):[...expanded.value,id]}
function showSearch(){searchOpen.value=true;nextTick(()=>searchField.value?.focus())}
function closeSearch(){search.value='';searchOpen.value=false}
function sort(value:string){sortBy.value=value;localStorage.setItem('flymind-list-sort',value);menu.value=null}
function beginGroup(){menu.value=null;groupName.value='';newGroup.value=true;nextTick(()=>groupField.value?.focus())}
function cancelNewGroup(restoreFocus=true){if(studio.pending)return;newGroup.value=false;groupName.value='';if(restoreFocus)void nextTick(()=>newGroupTrigger.value?.focus())}
function openMenu(type:'file'|'group'|'workspace',id:string,e:MouseEvent){if(props.readOnly&&type!=='workspace')return;menu.value={type,id,x:Math.max(8,Math.min(e.clientX,window.innerWidth-220)),y:Math.max(8,Math.min(e.clientY+8,window.innerHeight-295))}}
function rename(type:'file'|'group',id:string,name:string){renaming.value={type,id,name};menu.value=null;nextTick(()=>document.querySelector<HTMLInputElement>('.workspace-rename')?.select())}
async function finishRename(){const item=renaming.value;if(!item)return;renaming.value=null;if(!item.name.trim())return;if(item.type==='file')studio.renameDocument(item.id,item.name.trim());else await studio.renameWorkspaceGroup(item.id,item.name.trim())}
async function createGroup(){if(!groupName.value.trim())return;const name=groupName.value.trim();await studio.createWorkspaceGroup(name);if(!studio.storageError){newGroup.value=false;groupName.value='';const group=studio.workspaceGroups.find(g=>g.name===name);if(group){currentGroup.value=group.id;if(!expanded.value.includes(group.id))expanded.value.push(group.id)}}}
function deleteGroup(id:string){menu.value=null;if(window.confirm('删除分组？组内图形将移回主列表。'))studio.deleteWorkspaceGroup(id)}
function remove(id:string){menu.value=null;studio.deleteDocument(id);studio.notify('已移入回收站')}
async function move(id:string,group:string|null){if(props.readOnly)return;menu.value=null;await studio.moveToWorkspaceGroup(id,group);if(group&&!expanded.value.includes(group))expanded.value.push(group)}
async function duplicateFile(id:string){menu.value=null;if(props.adapter){await props.adapter.duplicateDocument(id);return;}const d=studio.documents.find(d=>d.id===id);if(!d)return;const group=studio.assignments[id];if((studio as unknown as ReturnType<typeof useStudio>).addDocument({...d as DiagramDocument,title:d.title+' · 副本'})&&group)await studio.moveToWorkspaceGroup(studio.activeId,group)}
function drop(e:DragEvent,group:string|null){dropGroup.value='';dragging.value=false;if(props.readOnly)return;if(Array.from(e.dataTransfer?.types??[]).includes('Files')){emit('file-drop',e,group);return;}const id=e.dataTransfer?.getData('application/x-flymind-diagram');if(id&&studio.documents.some(d=>d.id===id))move(id,group)}
function purge(item:SidebarAdapter['trash'][number]){if(window.confirm(`永久删除“${item.title}”？此操作无法从回收站恢复。`))studio.purgeDeleted(item)}
let stopResize:(()=>void)|undefined
function resizeSidebar(e:PointerEvent){e.preventDefault();const x=e.clientX,start=width.value,move=(p:PointerEvent)=>{width.value=Math.max(240,Math.min(420,start+p.clientX-x))},up=()=>{localStorage.setItem('flymind-sidebar-width',String(width.value));window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);stopResize=undefined};stopResize?.();stopResize=up;window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}
function outside(e:PointerEvent){if(!(e.target instanceof Element))return;if(!e.target.closest('.workspace-popup,.workspace-menu-trigger'))menu.value=null;if(newGroup.value&&!groupForm.value?.contains(e.target)&&!newGroupTrigger.value?.contains(e.target))cancelNewGroup(false)}
function shortcut(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'){menu.value=null;trashOpen.value=false;closeSearch();if(newGroup.value)cancelNewGroup()}}
onMounted(()=>{window.addEventListener('pointerdown',outside);window.addEventListener('keydown',shortcut)})
onUnmounted(()=>{stopResize?.();window.removeEventListener('pointerdown',outside);window.removeEventListener('keydown',shortcut)})
</script>
<style scoped>
.workspace-sidebar{position:relative;padding:14px 10px 10px;background:#f7f8fb;gap:0;min-width:240px;max-width:420px}.workspace-header{display:flex;align-items:center;gap:3px;margin-bottom:17px;padding:0 4px}.workspace-brand{margin-right:auto;gap:7px;padding:4px!important;color:#34435d}.workspace-brand strong{font-size:16px;letter-spacing:-.3px}.workspace-brand>svg{color:#9aa2b0}.workspace-header>.studio-icon{width:28px;height:28px;color:#8590a2}.workspace-search{display:flex;align-items:center;gap:7px;margin:0 4px 11px;border:1px solid #e0e4eb;border-radius:6px;background:#fff;color:#9aa2af;padding:4px 7px}.workspace-search input{width:100%;min-width:0;border:0;outline:0;background:none;font-size:12px}.workspace-search button{height:22px;width:22px;min-width:22px}
.workspace-tree{flex:1;min-height:0;overflow:auto}.workspace-group{margin-bottom:4px}.workspace-folder{display:flex;align-items:center;position:relative;border-radius:6px;min-height:33px}.workspace-folder:hover{background:#eceef4}.workspace-folder.drop,.workspace-root-files.drop{background:#ece8fa;box-shadow:inset 0 0 0 1px #b1a5e9}.workspace-folder-open{width:100%;min-width:0;justify-content:flex-start!important;gap:7px!important;padding:7px 32px 7px 5px!important}.workspace-folder-open>svg{color:#8993a4;flex-shrink:0}.workspace-folder-open>svg:first-child{color:#a2a8b3}.workspace-folder-open .collapsed{transform:rotate(-90deg)}.workspace-folder-open>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.workspace-group-files{padding-left:17px}.workspace-row-menu{position:absolute;right:4px;top:3px;width:27px;height:28px;padding:0!important;color:#9099a8;opacity:0;pointer-events:none}.workspace-folder:hover .workspace-row-menu,.workspace-row-menu:focus-visible{opacity:1;pointer-events:auto}.workspace-show-more{font-size:11px;color:#9aa1ad;margin:1px 0 7px 12px;padding:4px 0}.workspace-root-files{min-height:28px;border-radius:6px;padding-bottom:6px}.workspace-root-files.separated{margin-top:15px;padding-top:10px;border-top:1px solid #e7e9ef}.workspace-drop-hint{display:block;padding:10px;color:#9a91ba;text-align:center;font-size:11px}
.workspace-footer{border-top:1px solid #e7e9ef;padding:7px 3px 0;margin-top:8px}.workspace-footer button{width:100%;min-height:29px;justify-content:flex-start;padding:5px 9px;font-size:11px;color:#8c96a6}.workspace-resizer{position:absolute;right:-3px;top:0;width:6px;height:100%;cursor:ew-resize;z-index:8}.workspace-resizer:hover{background:#a69ee155}.workspace-popup{position:fixed;z-index:80;width:205px;padding:5px;border:1px solid #e4e7ee;background:#fff;border-radius:9px;box-shadow:0 10px 35px #24314920}.workspace-popup button{width:100%;justify-content:flex-start;padding:9px 10px;font-size:12px}.workspace-popup button[role=menuitemradio]>svg{margin-left:auto;color:#7465d5}.workspace-popup button:hover{background:#f0eff9}.workspace-popup label{display:block;padding:8px 10px;color:#8c94a2;font-size:11px}.workspace-popup select{display:block;width:100%;margin-top:6px;border:1px solid #e2e6ed;border-radius:5px;padding:5px;background:#fff;font-size:12px}.workspace-popup hr{margin:3px 5px;border:0;border-top:1px solid #edf0f4}.danger{color:#bc6262!important}.workspace-inline{display:flex;align-items:center;gap:6px;padding:5px}.workspace-inline input,.workspace-rename{min-width:0;width:100%;border:1px solid #b6a9ec;border-radius:5px;padding:5px 7px;background:#fff}.workspace-empty{padding:24px 10px;color:#a0a7b2;font-size:12px;text-align:center}
.workspace-trash-dialog{width:740px!important;max-width:90vw}.workspace-trash-list{max-height:58vh;overflow:auto}.workspace-trash-row{display:flex;align-items:center;gap:12px;padding:13px 4px;border-bottom:1px solid #edf0f4}.workspace-trash-row>svg{color:#98a2b4;flex-shrink:0}.workspace-trash-row>div{flex:1;min-width:0}.workspace-trash-row strong{display:block;font-weight:550;overflow-wrap:anywhere}.workspace-trash-row small{display:block;color:#99a2b0;font-size:11px;margin-top:3px}
</style>
